      }
    } else if (id === 'wrench') {
      ctx.beginPath(); ctx.moveTo(x - s * 0.3, y + s * 0.3); ctx.lineTo(x + s * 0.16, y - s * 0.16); ctx.stroke();
      ctx.beginPath(); ctx.arc(x + s * 0.22, y - s * 0.22, s * 0.16, 0.4, Math.PI * 1.65); ctx.stroke();
    }
