        }
        ctx.globalAlpha = 1;
        this.drawGlyph(d.require, d.x + d.w / 2, d.y + d.h / 2, 22, color, 0.8);
      }
      if (d.label) {
        ctx.fillStyle = 'rgba(210,240,228,.42)';
        ctx.font = '9px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.save();
        ctx.translate(d.x + d.w / 2 + (d.x < 20 ? 28 : -28), d.y + d.h / 2);
