    ctx.restore();
  }

  drawHint(h) {
    const ctx = this.ctx;
    ctx.save();
    ctx.fillStyle = 'rgba(160,255,225,.26)';
    ctx.font = '10px "Courier New", monospace'; ctx.textAlign = 'left';
    ctx.fillText(h.text, h.x, h.y);
