    ctx.moveTo(-9, -32); ctx.quadraticCurveTo(-12, -18, -8, -8); ctx.lineTo(8, -8); ctx.quadraticCurveTo(12, -20, 9, -32); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#182724';
    ctx.beginPath(); ctx.moveTo(-2, -31); ctx.lineTo(5, -31); ctx.lineTo(4, -12); ctx.lineTo(-3, -12); ctx.closePath(); ctx.fill();
    // Scarf
    const flow = Math.sin(t * 4) * 3 + (p.vx < -40 ? 5 : 0);
    ctx.strokeStyle = '#c95534'; ctx.lineWidth = 4; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-6, -32); ctx.quadraticCurveTo(-14, -31, -18 - flow, -26 + Math.sin(t * 5) * 2); ctx.stroke();
    ctx.strokeStyle = '#e07a4e'; ctx.lineWidth = 2;
