.ending-stats b { color: var(--amber); font-weight: 400; letter-spacing: 0.1em; }

/* ------------------------------------------------------------------ touch */
.touch {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 15;
  pointer-events: none;
}

.is-touch .touch { display: block; }

.touch::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 220px;
  background: linear-gradient(180deg, transparent, rgba(1, 5, 6, 0.5));
  pointer-events: none;
}

.touch-move,
.touch-actions {
  position: absolute;
  bottom: max(20px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  gap: 12px;
  pointer-events: none;
}

.touch-move { left: max(18px, env(safe-area-inset-left)); }
.touch-actions { right: max(18px, env(safe-area-inset-right)); }

.touch-btn {
  pointer-events: auto;
  touch-action: none;
  display: grid;
  place-items: center;
  border: 1px solid rgba(143, 245, 216, 0.28);
  background: rgba(5, 22, 21, 0.56);
  color: rgba(218, 255, 244, 0.78);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
  transition: transform 0.06s ease, background 0.06s ease, border-color 0.06s ease;
  font-size: 9px;
  letter-spacing: 0.1em;
}

.touch-btn.pressed {
  transform: scale(0.93);
  background: rgba(143, 245, 216, 0.28);
  border-color: rgba(190, 255, 238, 0.7);
}

.touch-btn.move {
  width: 66px;
  height: 66px;
  border-radius: 50%;
  font-size: 19px;
}

.touch-btn.act.small { width: 58px; height: 58px; border-radius: 50%; }
.touch-btn.act.big {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  border-color: rgba(255, 196, 107, 0.42);
  color: rgba(255, 228, 180, 0.88);
}

.touch-pause {
