import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
const t = Date.now()
try { await page.locator('#btn-new').click({ timeout: 5000 }); console.log('click ok', Date.now() - t) }
catch (e) { console.log('click fail', Date.now() - t, e.message.split('\n').slice(0, 12).join(' | ')) }
console.log('state', await page.evaluate(() => document.getElementById('title').className))
// check animations after hover by moving mouse manually and listing subtree animations
await page.mouse.move(650, 579)
await page.waitForTimeout(300)
console.log(await page.evaluate(() => {
  const title = document.getElementById('title')
  return title.getAnimations({ subtree: true }).map(a => ({ name: a.animationName, target: a.effect.target?.id || a.effect.target?.className, state: a.playState, time: Math.round(a.currentTime) }))
}))
await browser.close()

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
const el = page.locator('#btn-new')
const b0 = await el.boundingBox()
console.log('before hover', b0)
await page.mouse.move(b0.x + b0.width / 2, b0.y + b0.height / 2)
for (let i = 0; i < 12; i++) {
  await page.waitForTimeout(200)
  const b = await el.boundingBox()
  const anims = await page.evaluate(() => {
    const btn = document.querySelector('#btn-new')
    return btn.getAnimations({ subtree: true }).map(a => ({ name: a.animationName, state: a.playState, time: Math.round(a.currentTime) }))
  })
  console.log(i, b, anims)
}
await browser.close()
